#include <stdio.h>
#include <stdlib.h>

int *rent_one(int v) {
    int *p = malloc(sizeof(int));
    if (p == NULL) {
        return NULL;
    }
    *p = v;
    return p;
}

int main(void) {
    int rented = 0;
    int returned = 0;

    int *p = rent_one(5);
    rented++;
    printf("第 1 间放的是 %d\n", *p);
    free(p);
    returned++;

    p = rent_one(7);
    rented++;
    printf("第 2 间放的是 %d\n", *p);
    free(p);
    returned++;

    printf("账：租 %d 间，还 %d 间\n", rented, returned);
    if (rented == returned) {
        printf("对上了\n");
    } else {
        printf("漏了 %d 间\n", rented - returned);
    }
    return 0;
}

