    int *room[3];

    /* ↓ 在这儿写：先一间一间租下来、把牌子插进这一排的格子里；全部用完再一间一间还回去 */

    return 0;
}

items.referenceSolution:
#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int *room[3];

    for (int i = 0; i < 3; i++) {
        room[i] = malloc(sizeof(int));
        if (room[i] == NULL) {
            return 1;
        }
        *room[i] = (i + 1) * 2;
        printf("[租] 第 %d 间，放了 %d\n", i + 1, *room[i]);
    }

    for (int i = 0; i < 3; i++) {
        printf("[还] 第 %d 间，里头是 %d\n", i + 1, *room[i]);
        free(room[i]);
    }

    printf("收工\n");
    return 0;
}

